import cyclopts
from typing import Annotated

app = cyclopts.App()

@app.default
def deploy(
    target: str,
    token: Annotated[str, cyclopts.Parameter(help="API token", envvar="DEPLOY_TOKEN")]
) -> None:
    """Deploy to a target."""
    print(f"Deploying to {target} with token: {token}")

if __name__ == "__main__":
    app()
